package com.rancour.clan.ui;

import java.awt.BorderLayout;
import java.awt.GridLayout;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.function.Supplier;
import javax.swing.JButton;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.JTextArea;
import com.rancour.clan.models.DropCandidate;
import com.rancour.clan.models.MemberProfile;
import com.rancour.clan.models.PluginSettings;
import com.rancour.clan.services.DropChatNotifier;
import com.rancour.clan.services.DropService;

final class DropsPanel extends JPanel
{
	private final DropService service;
	private final JTextArea status = UiComponents.statusLabel("Waiting for a candidate drop");
	private final JPanel content = UiComponents.contentPanel();
	private final Supplier<String> activeRsn;
	private final Deque<DropCandidate> pendingCandidates = new ArrayDeque<>();
	private DropCandidate candidate;
	private MemberProfile profile;
	private boolean dropsVisible = true;
	private boolean dropsCanSubmit = true;
	private String restrictionMessage = "Drop submissions are currently disabled.";

	DropsPanel(DropService service)
	{
		this(service, () -> "");
	}

	DropsPanel(DropService service, Supplier<String> activeRsn)
	{
		super(new BorderLayout());
		this.service = service;
		this.activeRsn = activeRsn;
		content.add(UiComponents.heading("Drops"));
		content.add(UiComponents.card("Confirm drops", "Detected drops appear here.", "", RancourTheme.INFO));
		JPanel controls = new JPanel(new BorderLayout());
		controls.add(status, BorderLayout.CENTER);
		add(UiComponents.page(controls, content), BorderLayout.CENTER);
	}

	void offerCandidate(DropCandidate newCandidate)
	{
		if (!dropsVisible)
		{
			showDisabled();
			return;
		}
		if (candidate != null)
		{
			pendingCandidates.addLast(newCandidate);
			updateCandidateStatus();
			return;
		}
		showCandidate(newCandidate, true);
	}

	private void showCandidate(DropCandidate newCandidate, boolean notify)
	{
		candidate = newCandidate;
		if (notify)
		{
			DropChatNotifier.notify("Rancour PvM: A drop is ready to submit. Check the Rancour PvM plugin panel.");
		}
		String currentRsn = UiComponents.value(activeRsn.get()).trim();
		boolean loggedIn = !currentRsn.isEmpty();
		boolean linked = loggedIn && profile != null && profile.isLinkedRsn(currentRsn);
		content.removeAll();
		content.add(UiComponents.heading("Drops"));
		JPanel card = UiComponents.detailsCard(newCandidate.getItemName(), "", RancourTheme.WARNING,
			"Source", newCandidate.getSource(),
			"RSN", newCandidate.getRsn(),
			"Detected", UiComponents.shortDate(newCandidate.getDetectedAt()),
			"Method", newCandidate.getDetectionMethod());
		if (!loggedIn)
		{
			card.add(UiComponents.wrapped("Log in to confirm active RSN."));
		}
		else if (!linked)
		{
			card.add(UiComponents.wrapped("This RuneLite account is not linked to your Discord profile."));
		}
		JPanel actions = new JPanel(new GridLayout(2, 1, 0, 4));
		JButton confirm = UiComponents.successButton("Confirm Submit");
		JButton dismiss = UiComponents.neutralButton("Dismiss");
		confirm.addActionListener(event -> submit());
		dismiss.addActionListener(event -> advanceCandidate("Candidate dismissed"));
		actions.add(confirm);
		actions.add(dismiss);
		confirm.setEnabled(linked && dropsCanSubmit);
		card.add(actions);
		content.add(card);
		status.setForeground(linked && dropsCanSubmit ? RancourTheme.WARNING : RancourTheme.DANGER);
		updateCandidateStatus();
		content.revalidate();
		content.repaint();
	}

	private void updateCandidateStatus()
	{
		if (candidate == null)
		{
			return;
		}
		String currentRsn = UiComponents.value(activeRsn.get()).trim();
		boolean linked = !currentRsn.isEmpty() && profile != null && profile.isLinkedRsn(currentRsn);
		if (!linked || !dropsCanSubmit)
		{
			status.setText(restrictionMessage);
			return;
		}
		int queued = pendingCandidates.size();
		status.setText(queued == 0
			? "Review candidate before submitting"
			: "Review candidate before submitting (" + queued + " more pending)");
	}

	void setProfile(MemberProfile profile)
	{
		this.profile = profile;
	}

	void setDropsPanelEnabled(boolean enabled)
	{
		this.dropsVisible = enabled;
		this.dropsCanSubmit = enabled;
		if (!enabled)
		{
			showDisabled();
		}
		else if (candidate == null)
		{
			showIdle("Drop submissions enabled");
		}
	}

	void applySettings(PluginSettings settings)
	{
		if (settings == null)
		{
			return;
		}
		this.dropsVisible = settings.isDropsVisible();
		this.dropsCanSubmit = settings.canSubmitDrops();
		this.restrictionMessage = UiComponents.value(settings.getDropsRestrictionMessage()).isEmpty()
			? "Drop submissions are currently disabled."
			: settings.getDropsRestrictionMessage();
		if (!dropsVisible)
		{
			showDisabled();
		}
		else if (candidate == null)
		{
			showIdle("Waiting for a candidate drop");
		}
		else
		{
			updateCandidateStatus();
		}
	}

	void showDisabled()
	{
		candidate = null;
		pendingCandidates.clear();
		content.removeAll();
		content.add(UiComponents.heading("Drops"));
		content.add(UiComponents.card("Drops disabled", restrictionMessage, "", RancourTheme.DANGER));
		status.setText("Disabled");
		status.setForeground(RancourTheme.DANGER);
		content.revalidate();
		content.repaint();
	}

	private void showIdle(String message)
	{
		content.removeAll();
		content.add(UiComponents.heading("Drops"));
		content.add(UiComponents.card("No pending drop", "No candidate drop is awaiting confirmation.", "",
			RancourTheme.INFO));
		status.setText(message);
		status.setForeground(RancourTheme.MUTED);
		content.revalidate();
		content.repaint();
	}

	private void submit()
	{
		DropCandidate pending = candidate;
		if (pending == null)
		{
			return;
		}
		status.setText("Submitting confirmed drop...");
		status.setForeground(RancourTheme.WARNING);
		service.submit(pending.toSubmission()).whenComplete((result, error) -> SwingUtilities.invokeLater(() ->
		{
			if (error != null)
			{
				status.setText("Error: " + UiComponents.errorMessage(error));
				status.setForeground(RancourTheme.DANGER);
				return;
			}
			DropChatNotifier.notify("Rancour PvM: Your drop has been submitted successfully.");
			advanceCandidate("Submitted: " + result.getStatus() + " - " + result.getMessage());
		}));
	}

	private void advanceCandidate(String message)
	{
		candidate = null;
		DropCandidate next = pendingCandidates.pollFirst();
		if (next != null)
		{
			showCandidate(next, false);
			return;
		}
		showIdle(message);
		status.setText(message);
		status.setForeground(message.startsWith("Submitted:") ? RancourTheme.SUCCESS : RancourTheme.MUTED);
	}
}

package com.rancour.clan.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.time.Duration;
import java.time.Instant;
import java.time.format.DateTimeParseException;
import java.util.List;
import javax.swing.JButton;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.JTextArea;
import com.rancour.clan.models.ClanEvent;
import com.rancour.clan.services.EventService;

final class EventsPanel extends JPanel
{
	private final EventService service;
	private final JTextArea status = UiComponents.statusLabel("Not loaded");
	private final JPanel content = UiComponents.contentPanel();
	private boolean loading;

	EventsPanel(EventService service)
	{
		super(new BorderLayout());
		this.service = service;
		JButton refresh = new JButton("Refresh");
		refresh.addActionListener(event -> refresh());
		JPanel controls = new JPanel(new BorderLayout());
		controls.add(refresh, BorderLayout.CENTER);
		controls.add(status, BorderLayout.SOUTH);
		add(UiComponents.page(controls, content), BorderLayout.CENTER);
		refresh();
	}

	void refresh()
	{
		if (loading)
		{
			return;
		}
		loading = true;
		status.setText("Loading events...");
		service.loadEvents().whenComplete((items, error) -> SwingUtilities.invokeLater(() -> render(items, error)));
	}

	private void render(List<ClanEvent> items, Throwable error)
	{
		loading = false;
		content.removeAll();
		content.add(UiComponents.heading("Events"));
		if (error != null)
		{
			status.setText("Error: " + UiComponents.errorMessage(error));
			content.add(UiComponents.wrapped("Events are unavailable."));
		}
		else if (items == null || items.isEmpty())
		{
			status.setText("No upcoming events");
			content.add(UiComponents.wrapped("No events available for your Discord roles."));
		}
		else
		{
			status.setText(items.size() + " event(s)");
			for (ClanEvent item : items)
			{
				JPanel card = eventCard(item);
				JTextArea badge = visibilityBadge(item);
				if (badge != null)
				{
					card.add(badge);
				}
				content.add(card);
			}
			content.add(UiComponents.small("Last updated " + UiComponents.nowShort()));
		}
		content.revalidate();
		content.repaint();
	}

	private static JPanel eventCard(ClanEvent item)
	{
		String notes = visibleNotes(item);
		if (hasStarted(item))
		{
			return UiComponents.detailsCard(item.getName(), "", eventAccent(item),
				"Event", "EVENT STARTED",
				"Ends", endCountdown(item.getEndTime()),
				"Notes", notes);
		}
		return UiComponents.detailsCard(item.getName(), "", eventAccent(item),
			"Starts", UiComponents.shortDate(item.getStartTime()),
			"Countdown", countdown(item.getStartTime()),
			"Ends", endCountdown(item.getEndTime()),
			"Notes", notes);
	}

	private static String visibleNotes(ClanEvent item)
	{
		String raw = UiComponents.value(item.getNotes()).trim();
		if (raw.isEmpty())
		{
			return "None";
		}
		StringBuilder visible = new StringBuilder();
		for (String line : raw.split("\\R"))
		{
			String trimmed = line.trim();
			if (isDiscordTagLine(trimmed))
			{
				continue;
			}
			if (visible.length() > 0)
			{
				visible.append('\n');
			}
			visible.append(line);
		}
		String result = visible.toString().trim();
		return result.isEmpty() ? "None" : result;
	}

	private static boolean isDiscordTagLine(String line)
	{
		String normalized = UiComponents.value(line).trim().toLowerCase();
		return normalized.startsWith("tag:")
			|| normalized.startsWith("tags:")
			|| normalized.startsWith("event tag:")
			|| normalized.startsWith("event tags:")
			|| normalized.startsWith("discord tag:")
			|| normalized.startsWith("discord tags:");
	}

	private static Color eventAccent(ClanEvent event)
	{
		if ("cancelled".equalsIgnoreCase(event.getStatus()) || "closed".equalsIgnoreCase(event.getStatus()))
		{
			return RancourTheme.DISABLED;
		}
		try
		{
			Instant start = Instant.parse(event.getStartTime());
			Duration until = Duration.between(Instant.now(), start);
			if (!until.isNegative() && until.toHours() <= 24)
			{
				return RancourTheme.WARNING;
			}
			if (until.isNegative())
			{
				return RancourTheme.DISABLED;
			}
		}
		catch (DateTimeParseException ignored)
		{
			return RancourTheme.INFO;
		}
		return RancourTheme.INFO;
	}

	private static JTextArea visibilityBadge(ClanEvent event)
	{
		String visibility = UiComponents.value(event.getVisibility()).trim();
		if ("staff".equalsIgnoreCase(visibility))
		{
			return UiComponents.badge("STAFF EVENT", RancourTheme.BRAND_RED);
		}
		if ("restricted".equalsIgnoreCase(visibility))
		{
			return UiComponents.badge("RESTRICTED", RancourTheme.WARNING);
		}
		return null;
	}

	private static String countdown(String startTime)
	{
		try
		{
			Duration duration = Duration.between(Instant.now(), Instant.parse(startTime));
			boolean past = duration.isNegative();
			Duration absolute = past ? duration.negated() : duration;
			long days = absolute.toDays();
			long hours = absolute.minusDays(days).toHours();
			long minutes = absolute.minusDays(days).minusHours(hours).toMinutes();
			String value;
			if (days > 0)
			{
				value = days + "d " + hours + "h";
			}
			else if (hours > 0)
			{
				value = hours + "h " + minutes + "m";
			}
			else
			{
				value = Math.max(0, minutes) + "m";
			}
			return past ? "Started " + value + " ago" : "Starts in " + value;
		}
		catch (DateTimeParseException ignored)
		{
			return "Unknown";
		}
	}

	private static boolean hasStarted(ClanEvent event)
	{
		try
		{
			return !Instant.now().isBefore(Instant.parse(event.getStartTime()));
		}
		catch (DateTimeParseException ignored)
		{
			return false;
		}
	}

	private static String endCountdown(String endTime)
	{
		if (UiComponents.value(endTime).isEmpty())
		{
			return "Unknown";
		}
		try
		{
			Duration duration = Duration.between(Instant.now(), Instant.parse(endTime));
			boolean past = duration.isNegative();
			Duration absolute = past ? duration.negated() : duration;
			long days = absolute.toDays();
			long hours = absolute.minusDays(days).toHours();
			long minutes = absolute.minusDays(days).minusHours(hours).toMinutes();
			String value;
			if (days > 0)
			{
				value = days + "d " + hours + "h";
			}
			else if (hours > 0)
			{
				value = hours + "h " + minutes + "m";
			}
			else
			{
				value = Math.max(0, minutes) + "m";
			}
			return past ? "Ended " + value + " ago" : "Ends in " + value;
		}
		catch (DateTimeParseException ignored)
		{
			return "Unknown";
		}
	}
}

package com.rancour.clan.ui;

import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.GridLayout;
import java.util.Collections;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;
import java.util.concurrent.ThreadLocalRandom;
import java.util.function.Supplier;
import javax.swing.JButton;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import net.runelite.client.ui.PluginPanel;
import com.rancour.clan.models.DropCandidate;
import com.rancour.clan.models.MemberProfile;
import com.rancour.clan.models.PluginSettings;
import com.rancour.clan.services.AnnouncementService;
import com.rancour.clan.services.DropService;
import com.rancour.clan.services.EventService;
import com.rancour.clan.services.PluginSettingsService;
import com.rancour.clan.services.StaffService;
import com.rancour.clan.services.TeamService;
import com.rancour.clan.services.VerificationService;

public final class RancourClanPanel extends PluginPanel
{
	private static final int AUTO_REFRESH_JITTER_MAX_MS = 20_000;

	private final DropsPanel dropsPanel;
	private final VerificationPanel verificationPanel;
	private final AnnouncementsPanel announcementsPanel;
	private final EventsPanel eventsPanel;
	private final TeamsPanel teamsPanel;
	private final JButton dropsButton;
	private final JButton staffButton;
	private final StaffPanel staffPanel;
	private final PluginSettingsService settingsService;
	private final VerificationService verificationService;
	private final CardLayout cardLayout;
	private final JPanel cards;
	private volatile String currentPage = "verification";
	private volatile boolean userSelectedPage;
	private volatile boolean lastVerifiedWithSession;
	private volatile boolean dropsPanelEnabled = true;
	private volatile boolean dropsVisible;
	private volatile boolean dropsCanSubmit;
	private volatile Set<String> approvedDropKeys = Collections.emptySet();
	private boolean automaticRefreshScheduled;

	public RancourClanPanel(VerificationService verificationService, AnnouncementService announcementService,
		EventService eventService, DropService dropService, TeamService teamService, StaffService staffService,
		boolean ignoredMockMode)
	{
		this(verificationService, announcementService, eventService, dropService, teamService, staffService);
	}

	public RancourClanPanel(VerificationService verificationService, AnnouncementService announcementService,
		EventService eventService, DropService dropService, TeamService teamService, StaffService staffService)
	{
		this(verificationService, announcementService, eventService, dropService, teamService,
			staffService, () -> java.util.concurrent.CompletableFuture.completedFuture(new PluginSettings(true, Collections.emptyList())),
			() -> "");
	}

	public RancourClanPanel(VerificationService verificationService, AnnouncementService announcementService,
		EventService eventService, DropService dropService, TeamService teamService, StaffService staffService,
		PluginSettingsService settingsService, boolean ignoredMockMode)
	{
		this(verificationService, announcementService, eventService, dropService, teamService,
			staffService, settingsService, () -> "");
	}

	public RancourClanPanel(VerificationService verificationService, AnnouncementService announcementService,
		EventService eventService, DropService dropService, TeamService teamService, StaffService staffService,
		PluginSettingsService settingsService)
	{
		this(verificationService, announcementService, eventService, dropService, teamService,
			staffService, settingsService, () -> "");
	}

	public RancourClanPanel(VerificationService verificationService, AnnouncementService announcementService,
		EventService eventService, DropService dropService, TeamService teamService, StaffService staffService,
		PluginSettingsService settingsService, Supplier<String> activeRsn)
	{
		super(false);
		this.verificationService = verificationService;
		this.settingsService = settingsService;
		setLayout(new BorderLayout());
		cardLayout = new CardLayout();
		cards = new JPanel(cardLayout);
		verificationPanel = new VerificationPanel(verificationService, activeRsn);
		announcementsPanel = new AnnouncementsPanel(announcementService);
		eventsPanel = new EventsPanel(eventService);
		teamsPanel = new TeamsPanel(teamService, activeRsn);
		dropsPanel = new DropsPanel(dropService, activeRsn);
		staffPanel = new StaffPanel(staffService, () ->
		{
			announcementsPanel.refresh();
			refreshSettings();
		});
		cards.add(verificationPanel, "verification");
		cards.add(announcementsPanel, "announcements");
		cards.add(eventsPanel, "events");
		cards.add(dropsPanel, "drops");
		cards.add(teamsPanel, "teams");
		cards.add(staffPanel, "staff");

		JPanel navigation = new JPanel(new GridLayout(3, 2, 4, 4));
		navigation.add(button("Verify", "verification"));
		navigation.add(button("News", "announcements"));
		navigation.add(button("Events", "events"));
		dropsButton = button("Drops", "drops");
		dropsButton.setVisible(false);
		navigation.add(dropsButton);
		navigation.add(button("Teams", "teams"));
		staffButton = button("Staff", "staff");
		staffButton.setVisible(false);
		navigation.add(staffButton);

		JPanel top = new JPanel(new BorderLayout());
		top.add(navigation, BorderLayout.CENTER);
		add(top, BorderLayout.NORTH);
		add(cards, BorderLayout.CENTER);
		verificationService.addProfileListener(profile -> SwingUtilities.invokeLater(() -> updateStaffAccess(profile)));
		lastVerifiedWithSession = verifiedWithSession(verificationService.getCurrentProfile());
		showPage(lastVerifiedWithSession ? "announcements" : "verification", false);
		verificationPanel.refresh();
		if (lastVerifiedWithSession)
		{
			refreshVerifiedData();
		}
	}

	public boolean acceptsDropCandidate(DropCandidate candidate)
	{
		return dropsVisible && dropsCanSubmit && approvedDropKeys.contains(normalizeDrop(candidate.getItemName()));
	}

	public void offerDropCandidate(DropCandidate candidate)
	{
		SwingUtilities.invokeLater(() -> dropsPanel.offerCandidate(candidate));
	}

	public void refreshAll()
	{
		if (automaticRefreshScheduled)
		{
			return;
		}
		automaticRefreshScheduled = true;
		int delay = ThreadLocalRandom.current().nextInt(AUTO_REFRESH_JITTER_MAX_MS + 1);
		Timer timer = new Timer(delay, event ->
		{
			((Timer) event.getSource()).stop();
			automaticRefreshScheduled = false;
			performAutomaticRefresh();
		});
		timer.setRepeats(false);
		timer.start();
	}

	private void performAutomaticRefresh()
	{
		verificationPanel.refresh();
		if (!lastVerifiedWithSession || verificationPanel.hasRefreshFailure())
		{
			return;
		}
		refreshVerifiedData();
	}

	private void refreshVerifiedData()
	{
		announcementsPanel.refresh();
		eventsPanel.refresh();
		teamsPanel.refreshIfIdle();
		refreshSettings();
		if (staffButton.isVisible())
		{
			staffPanel.refreshPending();
		}
	}

	private void updateStaffAccess(MemberProfile profile)
	{
		dropsPanel.setProfile(profile);
		boolean verifiedWithSession = verifiedWithSession(profile);
		boolean becameVerified = verifiedWithSession && !lastVerifiedWithSession;
		boolean lostVerification = !verifiedWithSession && lastVerifiedWithSession;
		lastVerifiedWithSession = verifiedWithSession;
		boolean staff = profile != null && profile.isStaff() && verifiedWithSession;
		staffButton.setVisible(staff);
		staffButton.getParent().revalidate();
		if (staff && !becameVerified)
		{
			staffPanel.refreshPending();
		}
		if (becameVerified)
		{
			showPage("announcements", false);
			userSelectedPage = false;
			refreshVerifiedData();
		}
		else if (lostVerification)
		{
			showPage("verification", false);
			userSelectedPage = false;
		}
	}

	private void refreshSettings()
	{
		settingsService.loadSettings().whenComplete((settings, error) -> SwingUtilities.invokeLater(() ->
		{
			if (error != null || settings == null)
			{
				return;
			}
			dropsPanelEnabled = settings.isDropsPanelEnabled();
			dropsVisible = settings.isDropsVisible();
			dropsCanSubmit = settings.canSubmitDrops();
			Set<String> keys = new HashSet<>();
			for (String drop : settings.getApprovedDrops())
			{
				keys.add(normalizeDrop(drop));
			}
			approvedDropKeys = keys;
			dropsButton.setVisible(dropsVisible);
			dropsPanel.applySettings(settings);
			staffPanel.applySettings(settings);
			dropsButton.getParent().revalidate();
			if (!dropsVisible)
			{
				dropsPanel.showDisabled();
				if ("drops".equals(currentPage))
				{
					showPage(lastVerifiedWithSession ? "announcements" : "verification", false);
				}
			}
		}));
	}

	private static String normalizeDrop(String value)
	{
		return UiComponents.value(value).toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+", "");
	}

	boolean isStaffButtonVisible()
	{
		return staffButton.isVisible();
	}

	boolean isDropsButtonVisible()
	{
		return dropsButton.isVisible();
	}

	private boolean verifiedWithSession(MemberProfile profile)
	{
		return profile != null && !UiComponents.value(verificationService.getSessionToken()).trim().isEmpty();
	}

	private void showPage(String page, boolean manual)
	{
		currentPage = page;
		if (manual)
		{
			userSelectedPage = true;
		}
		cardLayout.show(cards, page);
	}

	String currentPage()
	{
		return currentPage;
	}

	boolean hasUserSelectedPage()
	{
		return userSelectedPage;
