			"Dragon claws",
			"Chambers of Xeric",
			"MX Plaid"
		);
		assertEquals("Dragon claws", candidate.getItemName());
		assertEquals("Chambers of Xeric", candidate.getSource());
		assertEquals("loot_tracker", candidate.getDetectionMethod());
	}

